import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DIZxrxCz.js";var i=JSON.parse(`{"title":"Story Points","description":"Story points are a unit for relatively estimating the size, complexity, and uncertainty of work. They do not map directly to absolute time, and their purpose is to determine a reasonable workload per sprint and estimate the team's schedule.","frontmatter":{"title":"Story Points","description":"Story points are a unit for relatively estimating the size, complexity, and uncertainty of work. They do not map directly to absolute time, and their purpose is to determine a reasonable workload per sprint and estimate the team's schedule.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban Introduction, Scrumban Concept, What is Scrumban, Scrumban vs Kanban, Agile Methodology, Agile Framework, Kanban Methodology, Scrum Methodology, Scrumban Process, Scrumban Operation Guide, Scrumban Board, WIP Limit, Workflow Management, How to use Kanban Board, Scrumban Advantages, Scrumban Features, Scrumban Effects, Scrumban Use Cases, Scrumban Introduction Effects, Scrumban Jira Setup, Scrumban Board Template, Scrumban Tool, Scrumban Collaboration Tool, Scrumban Workflow, Agile Project Management, Work Efficiency Methodology, Iterative Work Management, Bottleneck Resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/glossaryOfTerms.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/agile/storyPointGuide.html"}]],"sort":2000},"headers":[],"relativePath":"en/agile/storyPointGuide.md","filePath":"en/agile/storyPointGuide.md","lastUpdated":1785467839000}`),a={name:`en/agile/storyPointGuide.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="story-point-guide-work-estimation-method-for-agile-teams" tabindex="-1">Story Point Guide: Work Estimation Method for Agile Teams <a class="header-anchor" href="#story-point-guide-work-estimation-method-for-agile-teams" aria-label="Permalink to “Story Point Guide: Work Estimation Method for Agile Teams”">​</a></h1><h2 id="what-are-story-points" tabindex="-1">What are Story Points? <a class="header-anchor" href="#what-are-story-points" aria-label="Permalink to “What are Story Points?”">​</a></h2><p>Story points are a unit for relatively estimating the <strong>size, complexity, and uncertainty</strong> of work. They do not map directly to absolute time, and their purpose is to determine a reasonable workload per sprint and estimate the team&#39;s schedule.</p><blockquote><p>❌ The approach of &quot;5 points = 5 times the time of 1 point&quot; is incorrect.</p></blockquote><h2 id="reason-for-using-the-fibonacci-sequence" tabindex="-1">Reason for Using the Fibonacci Sequence <a class="header-anchor" href="#reason-for-using-the-fibonacci-sequence" aria-label="Permalink to “Reason for Using the Fibonacci Sequence”">​</a></h2><p>Story point estimation generally uses the Fibonacci sequence, such as <strong>1, 2, 3, 5, 8, 13, 21...</strong>. The reasons for using a sequence rather than consecutive numbers are:</p><ul><li>The gaps become larger, reflecting uncertainty</li><li>The difference between 5 and 8 is clearer than the difference between 5 and 6</li><li>It reflects that complexity and risk increase exponentially for larger tasks</li><li>As a result, team consensus becomes easier, and over/under-estimation can be reduced</li></ul><h2 id="story-point-utilization-example" tabindex="-1">Story Point Utilization Example <a class="header-anchor" href="#story-point-utilization-example" aria-label="Permalink to “Story Point Utilization Example”">​</a></h2><table tabindex="0"><thead><tr><th>Work Item</th><th>Points</th><th>Description</th></tr></thead><tbody><tr><td>User Research</td><td>3 points</td><td>Work requiring relatively light effort</td></tr><tr><td>Wireframing</td><td>5 points</td><td>Simple work done after user research</td></tr><tr><td>UI Design</td><td>8 points</td><td>Work requiring coordination within the team</td></tr><tr><td>Dev Task</td><td>13 points</td><td>Complex work involving many elements</td></tr><tr><td>QA Testing</td><td>8 points</td><td>Complex but manageable level of work</td></tr></tbody></table><h2 id="baseline-task-examples" tabindex="-1">Baseline Task Examples <a class="header-anchor" href="#baseline-task-examples" aria-label="Permalink to “Baseline Task Examples”">​</a></h2><h3 id="story-point-5-user-password-reset-feature" tabindex="-1">Story Point 5: User Password Reset Feature <a class="header-anchor" href="#story-point-5-user-password-reset-feature" aria-label="Permalink to “Story Point 5: User Password Reset Feature”">​</a></h3><p><strong>Definition of Done</strong></p><ul><li>Implement password change feature</li><li>Implement email verification feature</li><li>Comply with password rules (alphanumeric, etc.)</li></ul><p><strong>Supplementary Considerations</strong></p><ul><li>DB table design</li><li>Email sending/receiving environment</li><li>Exceptions do not need to be considered</li></ul><h3 id="story-point-13-credit-card-payment-feature" tabindex="-1">Story Point 13: Credit Card Payment Feature <a class="header-anchor" href="#story-point-13-credit-card-payment-feature" aria-label="Permalink to “Story Point 13: Credit Card Payment Feature”">​</a></h3><p><strong>Definition of Done</strong></p><ul><li>Implement product payment feature</li><li>Purchase history can be viewed on My Page</li><li>Admins can also check</li></ul><p><strong>Supplementary Considerations</strong></p><ul><li>Card registration feature already exists</li><li>DB design required</li><li>Error patterns do not need to be considered</li></ul><h2 id="caution-incorrect-usage" tabindex="-1">Caution: Incorrect Usage <a class="header-anchor" href="#caution-incorrect-usage" aria-label="Permalink to “Caution: Incorrect Usage”">​</a></h2><p><strong>Avoid the method of directly substituting time.</strong></p><ul><li>❌ &quot;A 4-hour task = 1 point&quot; → No different from the existing method</li><li>❌ &quot;5 points = 5 times the time of 1 point&quot;</li></ul><p><strong>Correct meaning</strong>: It means it is 5 times more complex than 1 point. Such incorrect approaches destroy the essence of story points.</p><h2 id="refactoring-and-quality-considerations" tabindex="-1">Refactoring and Quality Considerations <a class="header-anchor" href="#refactoring-and-quality-considerations" aria-label="Permalink to “Refactoring and Quality Considerations”">​</a></h2><p>Every story must include the following two elements:</p><ol><li>A feature that <strong>works properly</strong></li><li>Quality that ensures it <strong>operates correctly</strong></li></ol><p>If only the first element is satisfied and the second is ignored, the story point is incomplete. Refactoring work can also be assigned points from the perspective of quality improvement (removing technical debt).</p><blockquote><p>Caution: Never use story points to compare individual performance. This is purely a team-level tool.</p></blockquote><h2 id="core-summary" tabindex="-1">Core Summary <a class="header-anchor" href="#core-summary" aria-label="Permalink to “Core Summary”">​</a></h2><ul><li>Story points are a <strong>relative estimation unit</strong></li><li>The purpose is to <strong>compare complexity/uncertainty</strong> of work, not to convert it to time</li><li>Using the Fibonacci sequence reflects that risks increase as the work gets larger</li><li>Establish team consensus criteria (e.g., 3, 5, 8, 13) and make decisions by comparing new tasks</li><li>Avoid incorrect time mapping methods and ensure quality standards are reflected</li></ul><hr><h1 id="story-point-meeting-guide" tabindex="-1">Story Point Meeting Guide <a class="header-anchor" href="#story-point-meeting-guide" aria-label="Permalink to “Story Point Meeting Guide”">​</a></h1><h2 id="meeting-agenda" tabindex="-1">Meeting Agenda <a class="header-anchor" href="#meeting-agenda" aria-label="Permalink to “Meeting Agenda”">​</a></h2><h3 id="opening-5-mins" tabindex="-1">Opening (5 mins) <a class="header-anchor" href="#opening-5-mins" aria-label="Permalink to “Opening (5 mins)”">​</a></h3><ul><li>Explain the purpose of the meeting: Relatively estimate the difficulty/complexity of tasks for this sprint</li><li>Emphasize reaching a consensus through relative size comparison, not absolute time units</li></ul><h3 id="basic-concepts-reminder-10-mins" tabindex="-1">Basic Concepts Reminder (10 mins) <a class="header-anchor" href="#basic-concepts-reminder-10-mins" aria-label="Permalink to “Basic Concepts Reminder (10 mins)”">​</a></h3><ul><li>Definition of story points: A unit representing the size, complexity, and uncertainty of work</li><li>Does not match 1:1 with time (❌ &quot;5 points = 5 times the time of 1 point&quot;)</li><li>Explain why the Fibonacci sequence is used (1, 2, 3, 5, 8, 13, 21...)</li></ul><h3 id="share-baseline-examples-10-mins" tabindex="-1">Share Baseline Examples (10 mins) <a class="header-anchor" href="#share-baseline-examples-10-mins" aria-label="Permalink to “Share Baseline Examples (10 mins)”">​</a></h3><ul><li>Share story point examples (User Research → 3, Wireframing → 5, etc.)</li><li>Review specific baseline tasks (5 points: password reset, 13 points: credit card payment)</li></ul><h3 id="caution-on-incorrect-usage-5-mins" tabindex="-1">Caution on Incorrect Usage (5 mins) <a class="header-anchor" href="#caution-on-incorrect-usage-5-mins" aria-label="Permalink to “Caution on Incorrect Usage (5 mins)”">​</a></h3><ul><li>Emphasize not to directly substitute time</li><li>&quot;5 points = 5 times the time of 1 point&quot; ❌</li><li>Correct interpretation: &quot;5 times more complex than 1 point&quot;</li></ul><h3 id="refactoring-and-quality-considerations-10-mins" tabindex="-1">Refactoring and Quality Considerations (10 mins) <a class="header-anchor" href="#refactoring-and-quality-considerations-10-mins" aria-label="Permalink to “Refactoring and Quality Considerations (10 mins)”">​</a></h3><ul><li>Every story must include [1] Works properly + [2] Operates correctly (Quality)</li><li>Points need to be allocated for refactoring/technical debt improvement depending on the situation</li><li>Reiterate that it is not for comparing individual performance</li></ul><h3 id="actual-work-estimation-30-40-mins" tabindex="-1">Actual Work Estimation (30~40 mins) <a class="header-anchor" href="#actual-work-estimation-30-40-mins" aria-label="Permalink to “Actual Work Estimation (30~40 mins)”">​</a></h3><ul><li>Review backlog items one by one</li><li>Discuss by comparing with baseline examples</li><li>Team consensus → Decide on one of the Fibonacci numbers (e.g., 3, 5, 8, 13)</li><li>Find a middle ground when there are issues or conflicting opinions</li></ul><h3 id="wrap-up-5-mins" tabindex="-1">Wrap-up (5 mins) <a class="header-anchor" href="#wrap-up-5-mins" aria-label="Permalink to “Wrap-up (5 mins)”">​</a></h3><ul><li>Summarize the story point results decided in the meeting</li><li>Notify that it will be reflected in the next sprint planning</li><li>Reiterate that &quot;Story points are a tool to help the team estimate schedules quickly and easily&quot;</li></ul><p>Story points are a useful tool for team productivity and schedule management, but they show their true value only when understood and used correctly.</p><hr>`,50)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};